{{-- Detail Pengajuan Peminjaman — responsive (fluid) layout --}}
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@500;600;700&family=Plus+Jakarta+Sans:wght@600;700&display=swap" rel="stylesheet">

<style>
  .pa, .pa *, .pa *::before, .pa *::after { box-sizing: border-box; }
  .pa {
    --pa-primary: #00288E;
    --pa-primary-2: #1E40AF;
    --pa-ink: #131B2E;
    --pa-muted: #444653;
    --pa-line: #C4C5D5;
    --pa-bg: #FAF8FF;
    --pa-s1: #F2F3FF;
    --pa-s2: #EAEDFF;
    --pa-s3: #E2E7FF;
    --pa-danger: #BA1A1A;
    --pa-danger-bg: #FFDAD6;
    --pa-warn: #9D4300;
    --pa-warn-ink: #783200;
    --pa-warn-bg: #FFDBCA;
    --pa-ok: #00563A;
    --pa-ok-2: #003D27;
    --pa-aside-w: 256px;
    --pa-head-h: 64px;
    --pa-shadow: 0 1px 2px rgba(0, 0, 0, .05);
    font-family: Inter, system-ui, -apple-system, "Segoe UI", sans-serif;
    font-size: 13px;
    line-height: 18px;
    color: var(--pa-ink);
    background: var(--pa-bg);
    min-height: 100vh;
    width: 100%;
    -webkit-font-smoothing: antialiased;
  }
  .pa svg { flex: none; display: block; }
  .pa img { display: block; max-width: 100%; }
  .pa a { color: inherit; text-decoration: none; }
  .pa button { font: inherit; cursor: pointer; border: 0; background: none; color: inherit; }
  .pa h1, .pa h2, .pa h3, .pa p { margin: 0; }
  .pa .mono { font-family: "JetBrains Mono", ui-monospace, Menlo, monospace; }
  .pa .head-font { font-family: "Plus Jakarta Sans", Inter, sans-serif; }

  /* ---------- Sidebar ---------- */
  .pa-aside {
    position: fixed; inset: 0 auto 0 0; width: var(--pa-aside-w);
    background: var(--pa-primary-2); box-shadow: 0 1px 8px rgba(0, 0, 0, .08);
    display: flex; flex-direction: column; justify-content: space-between;
    overflow-y: auto; z-index: 60; transition: transform .25s ease;
  }
  .pa-brand { height: var(--pa-head-h); padding: 0 16px; display: flex; align-items: center; gap: 8px; background: rgba(0, 40, 142, .25); }
  .pa-brand-logo { width: 36px; height: 36px; border-radius: 8px; background: rgba(255, 255, 255, .1); display: grid; place-items: center; }
  .pa-brand b { display: block; color: #fff; font-size: 16px; line-height: 20px; font-family: "Plus Jakarta Sans", Inter, sans-serif; font-weight: 700; }
  .pa-brand small { display: block; color: #B8C4FF; font-size: 10px; line-height: 10px; letter-spacing: .5px; text-transform: uppercase; }
  .pa-nav-label { padding: 8px 24px; color: rgba(184, 196, 255, .8); font-size: 11px; line-height: 14px; font-weight: 600; letter-spacing: .55px; text-transform: uppercase; }
  .pa-nav { padding: 0 12px; display: flex; flex-direction: column; gap: 4px; }
  .pa-nav a { display: flex; align-items: center; gap: 10px; padding: 8px 12px; border-radius: 4px; color: #DDE1FF; font-size: 14px; line-height: 20px; min-width: 0; overflow: hidden; }
  .pa-nav a:hover { background: rgba(255, 255, 255, .1); }
  .pa-nav a.is-active { background: rgba(255, 255, 255, .2); }
  .pa-nav a.is-strong { color: #fff; font-weight: 600; }
  .pa-nav a svg { flex: none; }
  .pa-nav a .label { flex: 1 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: normal; line-height: 1.3; }
  .pa-nav-badge { padding: 2px 6px; border-radius: 2px; font-size: 12px; line-height: 16px; font-weight: 600; color: #fff; white-space: nowrap; flex: none; margin-left: auto; }
  .pa-nav-badge.warn { background: #FD761A; }
  .pa-nav-badge.soft { background: rgba(255, 255, 255, .2); color: #DDE1FF; font-family: "JetBrains Mono", monospace; }
  .pa-nav hr { width: 100%; height: 1px; border: 0; margin: 8px 0; background: rgba(255, 255, 255, .18); }
  .pa-user-box { margin: 0; padding: 12px; background: rgba(0, 40, 142, .2); }
  .pa-user-box > div { padding: 8px; background: rgba(255, 255, 255, .05); border-radius: 8px; display: flex; align-items: center; gap: 8px; }
  .pa-avatar-sm { width: 36px; height: 36px; border-radius: 8px; background: #3755C3; color: #fff; display: grid; place-items: center; font: 700 13px/16px "Plus Jakarta Sans", Inter, sans-serif; flex: none; }
  .pa-user-box .info { flex: 1; min-width: 0; }
  .pa-user-box .info b { display: block; color: #fff; font-size: 13px; font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  .pa-user-box .info span { display: flex; align-items: center; gap: 4px; color: #B8C4FF; font-size: 11px; }
  .pa-user-box .info i { width: 6px; height: 6px; border-radius: 50%; background: #6FFBBE; }
  .pa-user-box button { padding: 4px; border-radius: 4px; }
  .pa-user-box button:hover { background: rgba(255, 255, 255, .1); }
  .pa-backdrop { display: none; position: fixed; inset: 0; background: rgba(19, 27, 46, .5); z-index: 55; }

  /* ---------- Content shell ---------- */
  .pa-content { margin-left: var(--pa-aside-w); min-width: 0; }
  .pa-header {
    position: sticky; top: 0; z-index: 40; height: var(--pa-head-h); padding: 0 24px;
    display: flex; align-items: center; gap: 12px;
    background: rgba(255, 255, 255, .95); box-shadow: 0 1px 8px rgba(0, 0, 0, .04);
    -webkit-backdrop-filter: blur(12px); backdrop-filter: blur(12px);
  }
  .pa-burger { display: none; width: 36px; height: 36px; border-radius: 4px; background: var(--pa-s1); place-items: center; flex: none; }
  .pa-switcher { display: flex; align-items: center; gap: 6px; padding: 4px 12px; min-height: 36px; border-radius: 4px; background: var(--pa-s1); font-weight: 600; max-width: 260px; min-width: 0; }
  .pa-switcher span { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  .pa-vdiv { width: 1px; height: 24px; background: #DAE2FD; flex: none; }
  .pa-search { flex: 1 1 200px; max-width: 360px; min-width: 0; display: flex; align-items: center; gap: 6px; padding: 6px 12px; border-radius: 4px; background: #fff; box-shadow: 0 1px 4px rgba(0, 0, 0, .06); }
  .pa-search input { flex: 1; min-width: 0; border: 0; outline: 0; background: transparent; font: inherit; color: var(--pa-ink); }
  .pa-search input::placeholder { color: var(--pa-muted); }
  .pa-sem { display: flex; align-items: center; gap: 4px; padding: 4px 12px; border-radius: 8px; background: var(--pa-s2); color: var(--pa-muted); font-size: 12px; line-height: 16px; font-weight: 600; white-space: nowrap; }
  .pa-head-right { margin-left: auto; display: flex; align-items: center; gap: 12px; flex: none; }
  .pa-bell { position: relative; width: 36px; height: 36px; border-radius: 4px; background: var(--pa-s1); display: grid; place-items: center; }
  .pa-bell i { position: absolute; top: 6px; right: 6px; width: 8px; height: 8px; border-radius: 50%; background: var(--pa-warn); }
  .pa-me { display: flex; align-items: center; gap: 8px; padding-left: 8px; }
  .pa-me .txt { text-align: right; }
  .pa-me .txt b { display: block; font-size: 13px; font-weight: 600; white-space: nowrap; }
  .pa-me .txt span { display: block; color: var(--pa-muted); font-size: 12px; line-height: 16px; white-space: nowrap; }
  .pa-me .ava { width: 32px; height: 32px; border-radius: 12px; background: var(--pa-primary); display: grid; place-items: center; }

  .pa-main { padding: 24px; max-width: 1480px; margin: 0 auto; }

  /* ---------- Title bar ---------- */
  .pa-crumb { display: flex; align-items: center; flex-wrap: wrap; gap: 4px; margin-bottom: 12px; color: var(--pa-muted); font-weight: 500; }
  .pa-crumb a { display: inline-flex; align-items: center; gap: 4px; }
  .pa-crumb code { padding: 2px 4px; border-radius: 2px; background: var(--pa-s3); color: var(--pa-primary); font: 600 12px/16px "JetBrains Mono", monospace; }
  .pa-titlebar { display: flex; flex-wrap: wrap; align-items: flex-end; justify-content: space-between; gap: 16px; margin-bottom: 24px; }
  .pa-titlebar h1 { font: 700 24px/32px "Plus Jakarta Sans", Inter, sans-serif; }
  .pa-pill { display: inline-flex; align-items: center; gap: 6px; margin-top: 12px; padding: 4px 12px; border-radius: 12px; background: var(--pa-warn-bg); color: var(--pa-warn-ink); box-shadow: var(--pa-shadow); font-size: 12px; line-height: 16px; font-weight: 600; letter-spacing: .12px; }
  .pa-pill i { width: 8px; height: 8px; border-radius: 50%; background: var(--pa-warn); flex: none; }
  .pa-actions { display: flex; flex-wrap: wrap; gap: 8px; }
  .pa-btn { display: inline-flex; align-items: center; justify-content: center; gap: 6px; min-height: 38px; padding: 0 14px; border-radius: 4px; font-size: 13px; line-height: 16px; font-weight: 500; text-align: center; box-shadow: var(--pa-shadow); }
  .pa-btn.white { background: #fff; color: var(--pa-ink); }
  .pa-btn.white:hover { background: var(--pa-s1); }
  .pa-btn.danger { background: var(--pa-danger-bg); color: var(--pa-danger); font-weight: 600; }
  .pa-btn.danger:hover { filter: brightness(.97); }
  .pa-btn.primary { background: var(--pa-primary); color: #fff; font-weight: 600; padding: 0 20px; box-shadow: 0 2px 4px -2px rgba(0, 0, 0, .1), 0 4px 6px -1px rgba(0, 0, 0, .1); }
  .pa-btn.primary:hover { background: #0a3399; }

  /* ---------- Grid ---------- */
  .pa-grid { display: grid; grid-template-columns: minmax(0, 1fr); gap: 24px; align-items: start; }
  .pa-col { display: flex; flex-direction: column; gap: 24px; min-width: 0; }
  .pa-card { position: relative; padding: 24px; background: #fff; border-radius: 8px; box-shadow: var(--pa-shadow); overflow: hidden; display: flex; flex-direction: column; gap: 20px; min-width: 0; }
  .pa-card-head { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 8px; position: relative; }
  .pa-card-head h2 { display: flex; align-items: center; gap: 8px; font: 600 16px/24px "Plus Jakarta Sans", Inter, sans-serif; }
  .pa-tag { display: inline-block; padding: 2px 8px; border-radius: 2px; font: 600 12px/16px "JetBrains Mono", monospace; white-space: nowrap; }
  .pa-tag.ok { background: var(--pa-ok); color: #3FD298; }
  .pa-tag.blue { background: var(--pa-s3); color: #173BAB; }
  .pa-tag.soft { background: var(--pa-s2); color: var(--pa-muted); font-weight: 500; }
  .pa-label { color: var(--pa-muted); font-size: 11px; line-height: 14px; font-weight: 600; letter-spacing: .55px; text-transform: uppercase; }

  /* Identity */
  .pa-deco { position: absolute; top: 0; right: 0; width: 128px; height: 128px; background: rgba(0, 40, 142, .05); border-bottom-left-radius: 12px; pointer-events: none; }
  .pa-profile { display: flex; gap: 20px; align-items: flex-start; }
  .pa-photo { position: relative; flex: none; width: 80px; height: 80px; }
  .pa-photo img { width: 80px; height: 80px; object-fit: cover; border-radius: 8px; box-shadow: var(--pa-shadow); }
  .pa-photo .ok { position: absolute; right: -6px; bottom: -6px; width: 22px; height: 22px; border-radius: 50%; background: var(--pa-ok-2); border: 2px solid #fff; display: grid; place-items: center; }
  .pa-who { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 4px; }
  .pa-who-top { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 4px 12px; }
  .pa-who h3 { font: 700 16px/24px "Plus Jakarta Sans", Inter, sans-serif; }
  .pa-who p { color: var(--pa-muted); }
  .pa-contact { display: flex; flex-wrap: wrap; align-items: center; gap: 6px 12px; padding-top: 4px; }
  .pa-contact span { display: inline-flex; align-items: center; gap: 4px; min-width: 0; overflow-wrap: anywhere; }
  .pa-contact .sep { width: 1px; height: 12px; background: var(--pa-line); }
  .pa-rep { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 12px; padding: 12px; border-radius: 4px; background: var(--pa-s1); }
  .pa-rep-l { display: flex; align-items: center; gap: 12px; min-width: 0; }
  .pa-rep-ico { width: 40px; height: 40px; border-radius: 4px; background: var(--pa-ok); display: grid; place-items: center; flex: none; }
  .pa-rep b { display: block; font-weight: 600; line-height: 16px; }
  .pa-rep p { color: var(--pa-muted); }
  .pa-score { display: flex; align-items: center; gap: 4px; padding: 4px 12px; border-radius: 4px; background: #fff; box-shadow: var(--pa-shadow); }
  .pa-score b { font: 700 16px/24px "Plus Jakarta Sans", Inter, sans-serif; }
  .pa-score small { color: var(--pa-muted); font-size: 12px; font-weight: 500; }
  .pa-docs-wrap { display: flex; flex-direction: column; gap: 8px; }
  .pa-docs { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 12px; }
  .pa-doc { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 12px; border-radius: 8px; background: var(--pa-s2); min-width: 0; }
  .pa-doc-l { display: flex; align-items: center; gap: 12px; min-width: 0; flex: 1; }
  .pa-ktm { position: relative; flex: none; width: 80px; height: 56px; border-radius: 4px; overflow: hidden; background: #D2D9F4; box-shadow: inset 0 2px 4px rgba(0, 0, 0, .05); }
  .pa-ktm img { width: 100%; height: 100%; object-fit: cover; }
  .pa-ktm .ov { position: absolute; inset: 0; background: rgba(0, 40, 142, .1); display: grid; place-items: center; }
  .pa-doc-txt { min-width: 0; display: flex; flex-direction: column; gap: 2px; }
  .pa-doc-txt b { display: flex; align-items: center; gap: 4px; font-weight: 600; line-height: 16px; }
  .pa-doc-txt b span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  .pa-doc-txt small { color: var(--pa-muted); font: 500 12px/16px "JetBrains Mono", monospace; }
  .pa-doc-txt small.ok { color: #005236; }
  .pa-doc-txt a.lnk { color: var(--pa-primary); font-size: 12px; line-height: 16px; font-weight: 500; }
  .pa-doc-txt a.lnk:hover { text-decoration: underline; }
  .pa-file-ico { width: 40px; height: 40px; border-radius: 4px; background: #DAE2FD; display: grid; place-items: center; flex: none; }
  .pa-icon-btn { width: 32px; height: 32px; border-radius: 4px; display: grid; place-items: center; flex: none; }
  .pa-icon-btn:hover { background: rgba(0, 40, 142, .08); }

  /* Asset */
  .pa-asset { display: flex; flex-wrap: wrap; gap: 20px; padding: 20px; border-radius: 8px; background: var(--pa-s1); }
  .pa-asset-img { position: relative; flex: 0 0 176px; height: 144px; border-radius: 4px; background: #fff; box-shadow: var(--pa-shadow); overflow: hidden; }
  .pa-asset-img img { width: 100%; height: 100%; object-fit: cover; }
  .pa-asset-img span { position: absolute; left: 6px; bottom: 6px; padding: 2px 4px; border-radius: 2px; background: rgba(255, 255, 255, .9); font: 700 12px/16px "JetBrains Mono", monospace; }
  .pa-asset-info { flex: 1 1 240px; min-width: 0; display: flex; flex-direction: column; justify-content: space-between; gap: 12px; }
  .pa-asset-info .row { display: flex; flex-wrap: wrap; align-items: center; gap: 4px 8px; }
  .pa-chip { padding: 2px 4px; border-radius: 2px; background: #DDE1FF; color: #001453; font-size: 12px; line-height: 16px; font-weight: 600; letter-spacing: .12px; }
  .pa-asset-info .sn { color: var(--pa-muted); font: 500 12px/16px "JetBrains Mono", monospace; }
  .pa-asset-info h3 { margin-top: 4px; font: 700 16px/22px "Plus Jakarta Sans", Inter, sans-serif; }
  .pa-cond { display: flex; align-items: center; gap: 8px; font-weight: 600; }
  .pa-cond i { width: 10px; height: 10px; border-radius: 50%; background: var(--pa-ok-2); flex: none; }
  .pa-asset-info p { color: var(--pa-muted); }
  .pa-avail { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 8px 16px; padding: 12px; border-radius: 4px; background: var(--pa-s2); }
  .pa-avail > div { display: flex; align-items: center; gap: 8px; min-width: 0; }
  .pa-avail .mono { color: var(--pa-muted); font-size: 12px; line-height: 16px; font-weight: 500; }
  .pa-kit { display: flex; flex-direction: column; gap: 8px; }
  .pa-kit ul { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: 8px; }
  .pa-kit li { display: flex; align-items: center; gap: 8px; min-height: 40px; padding: 8px; border-radius: 4px; background: var(--pa-s1); }
  .pa-kit li:last-child { grid-column: 1 / -1; }

  /* Schedule */
  .pa-times { display: grid; grid-template-columns: repeat(auto-fit, minmax(170px, 1fr)); gap: 12px; }
  .pa-time { padding: 12px; border-radius: 8px; background: var(--pa-s2); display: flex; flex-direction: column; gap: 4px; }
  .pa-time.end { background: var(--pa-s3); }
  .pa-time.sum { background: var(--pa-s1); justify-content: space-between; }
  .pa-time small { color: var(--pa-muted); font-size: 12px; line-height: 16px; font-weight: 500; letter-spacing: .12px; }
  .pa-time.end small { color: var(--pa-warn-ink); }
  .pa-time strong { font: 700 16px/24px "Plus Jakarta Sans", Inter, sans-serif; color: var(--pa-primary); }
  .pa-time.end strong { color: var(--pa-warn); }
  .pa-time .clock { display: flex; align-items: center; gap: 4px; font: 500 12px/16px "JetBrains Mono", monospace; }
  .pa-time .big { font: 700 28px/34px "Plus Jakarta Sans", Inter, sans-serif; color: var(--pa-ink); }
  .pa-time .free { color: var(--pa-ok); font-size: 12px; line-height: 16px; font-weight: 600; letter-spacing: .12px; }
  .pa-usage { display: flex; flex-direction: column; gap: 12px; }
  .pa-usage h3 { font-size: 13px; line-height: 16px; font-weight: 600; margin-bottom: 4px; }
  .pa-quote { padding: 12px; border-radius: 4px; background: var(--pa-s1); color: var(--pa-muted); font-size: 14px; line-height: 22.75px; }
  .pa-place { display: flex; align-items: center; gap: 8px; padding: 12px; border-radius: 4px; background: #fff; box-shadow: var(--pa-shadow); }
  .pa-place small { display: block; color: var(--pa-muted); font-size: 12px; line-height: 16px; font-weight: 500; letter-spacing: .12px; }
  .pa-place b { display: block; font-weight: 600; }

  /* Decision */
  .pa-decision { box-shadow: 0 2px 4px -2px rgba(0, 0, 0, .1), 0 4px 6px -1px rgba(0, 0, 0, .1); }
  .pa-decision h2 { display: flex; align-items: center; gap: 6px; font: 700 16px/24px "Plus Jakarta Sans", Inter, sans-serif; }
  .pa-field { display: flex; flex-direction: column; gap: 4px; }
  .pa-field label.t { font-weight: 600; line-height: 16px; }
  .pa-field textarea { width: 100%; min-height: 72px; resize: vertical; padding: 8px; border: 1px solid transparent; border-radius: 4px; background: #fff; box-shadow: var(--pa-shadow), inset 0 0 0 1px #E2E4EE; font: inherit; color: var(--pa-ink); }
  .pa-field textarea::placeholder { color: var(--pa-muted); }
  .pa-field textarea:focus { outline: 2px solid rgba(0, 40, 142, .35); outline-offset: 0; }
  .pa-checks { display: flex; flex-direction: column; gap: 8px; }
  .pa-check { display: flex; align-items: flex-start; gap: 8px; padding: 8px; border-radius: 4px; background: var(--pa-s1); font-weight: 500; line-height: 16.25px; cursor: pointer; }
  .pa-check input { width: 15px; height: 15px; margin: 1px 0 0; accent-color: var(--pa-primary); flex: none; }
  .pa-btns { display: flex; flex-direction: column; gap: 8px; padding-top: 4px; }
  .pa-btns .pa-btn { width: 100%; }
  .pa-btns .main { min-height: 44px; }
  .pa-btns .outline { background: #fff; color: var(--pa-danger); font-weight: 600; min-height: 40px; }
  .pa-btns .soft { background: var(--pa-s2); color: var(--pa-ink); min-height: 40px; box-shadow: none; }

  /* Timeline */
  .pa-log-head { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
  .pa-log-head h2 { font: 700 16px/24px "Plus Jakarta Sans", Inter, sans-serif; }
  .pa-log-head span { color: var(--pa-muted); font: 500 12px/16px "JetBrains Mono", monospace; }
  .pa-tl { position: relative; list-style: none; margin: 0; padding: 0 0 0 24px; display: flex; flex-direction: column; gap: 20px; }
  .pa-tl::before { content: ""; position: absolute; left: 8px; top: 8px; bottom: 8px; width: 2px; background: #DAE2FD; }
  .pa-tl li { position: relative; display: flex; flex-direction: column; gap: 2px; }
  .pa-tl li::before { content: ""; position: absolute; left: -24px; top: 2px; width: 18px; height: 18px; border-radius: 50%; background: var(--pa-primary); box-shadow: 0 0 0 4px #fff; }
  .pa-tl li.ok::before { background: var(--pa-ok-2); }
  .pa-tl li.now::before { background: var(--pa-warn); }
  .pa-tl li > div { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: baseline; gap: 2px 12px; }
  .pa-tl b { font-weight: 600; line-height: 16px; }
  .pa-tl time { color: var(--pa-muted); font: 500 12px/16px "JetBrains Mono", monospace; white-space: nowrap; }
  .pa-tl li.now time { color: var(--pa-warn); font-weight: 700; }
  .pa-tl p { color: var(--pa-muted); }

  /* ---------- Breakpoints ---------- */
  @media (min-width: 1100px) {
    .pa-grid { grid-template-columns: minmax(0, 1fr) clamp(300px, 34%, 420px); }
  }
  @media (min-width: 1100px) and (min-height: 1000px) {
    .pa-col.side { position: sticky; top: calc(var(--pa-head-h) + 24px); }
  }
  @media (max-width: 1023px) {
    .pa-aside { transform: translateX(-100%); }
    .pa.is-nav-open .pa-aside { transform: none; box-shadow: 8px 0 24px rgba(0, 0, 0, .25); }
    .pa.is-nav-open .pa-backdrop { display: block; }
    .pa-content { margin-left: 0; }
    .pa-burger { display: grid; }
  }
  @media (min-width: 1300px) {
    .pa-main {
      max-width: 1280px;
    }
  }
  @media (max-width: 900px) {
    .pa-sem { display: none; }
  }
  @media (max-width: 767px) {
    .pa-header { padding: 0 12px; gap: 8px; }
    .pa-main { padding: 16px 12px; }
    .pa-vdiv { display: none; }
    .pa-me .txt { display: none; }
    .pa-me { padding-left: 0; }
    .pa-switcher { padding: 4px 8px; max-width: 150px; }
    .pa-card { padding: 16px; gap: 16px; }
    .pa-titlebar h1 { font-size: 20px; line-height: 28px; }
  }
  @media (max-width: 640px) {
    .pa-actions { width: 100%; }
    .pa-actions .pa-btn { flex: 1 1 100%; }
    .pa-profile { gap: 14px; }
    .pa-deco { width: 80px; height: 80px; }
    .pa-asset { padding: 12px; }
    .pa-asset-img { flex-basis: 100%; height: 190px; }
    .pa-asset-img img { object-fit: contain; }
    .pa-docs { grid-template-columns: minmax(0, 1fr); }
    .pa-search { flex-basis: 0; }
  }
  @media (max-width: 420px) {
    .pa-profile { flex-direction: column; }
    .pa-switcher span { display: none; }
    .pa-switcher { max-width: none; }
    .pa-nav a { padding: 9px 8px; }
    .pa-nav a .label { font-size: 13px; }
    .pa-nav-badge { font-size: 10px; padding: 2px 5px; }
  }
  @media print {
    .pa-aside, .pa-header, .pa-actions, .pa-btns, .pa-backdrop { display: none !important; }
    .pa-content { margin-left: 0; }
  }
</style>

